#include "../../src/residual.hpp"
int main(){init_curve();auto chart=load_chart();for(auto[h,w]:std::vector<std::pair<F,F>>{{1,2},{31,2},{73,25}}){auto g=barred(evaluate(chart,h,w));auto qb=cm(0,1)*Curve(exactdiv(Q-power(B0,5),power(P,2)));auto D=universal_resultant(scale(g[0],3),scale(g[1],2),g[2],g[3],qb,Curve(power(t,3)));std::cout<<"h="<<h<<" w="<<w<<"\n";for(int k=0;k<3;k++){std::cout<<" ldegree="<<k<<"; component_degrees";for(int j=0;j<3;j++){auto [q,r]=divrem(D[k][j],power(t,5));std::cout<<" "<<D[k][j].deg()<<"/"<<q.deg()<<"/r"<<r.deg();}std::cout<<"\n";}auto discr=power(scale(g[1],2),2)+scale(g[0]*g[2],3);for(int j=0;j<3;j++)std::cout<<"delta component "<<j<<" deg="<<discr[j].deg()<<"\n";}}
